  --white: #ffffff;
  --muted: #d0d6e0;
  --max-width: 1100px;
}

.game-container {
  width: 100%;
  max-width: var(--max-width);
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.02),
    rgba(255, 255, 255, 0.01)
  );
  border-radius: 20px;
  padding: 28px;
  box-shadow: var(--card-shadow);
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 24px;
  align-items: start;
  margin: 24px auto;
}

.game-area {
  padding: 20px;
}

/* Header */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 12px;
}
.badge {
  background: linear-gradient(180deg, var(--gold), var(--gold-dark));
  color: #2a1a00;
  font-family: "Cinzel", serif;
  padding: 10px 14px;
  border-radius: 10px;
  box-shadow: var(--accent-glow);
  font-size: 20px;
  letter-spacing: 1px;
}
.logo-sub {
  color: var(--muted);
  font-size: 14px;
}
.balance {
  text-align: right;
  font-family: "Montserrat", sans-serif;
}
.balance small {
  display: block;
  color: var(--muted);
  font-size: 12px;
}
.balance .amt {
  font-size: 20px;
  color: var(--gold);
  font-weight: 700;
}

/* Reels */
.reel-board {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin: 12px 0 20px;
}
.reel {
  width: 140px;
  height: 190px;
  border-radius: 14px;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.02),
    rgba(255, 255, 255, 0.01)
  );
  border: 2px solid rgba(255, 214, 102, 0.14);
  box-shadow: 0 10px 30px rgba(10, 6, 20, 0.6),
    inset 0 -6px 18px rgba(0, 0, 0, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}
.symbols {
  display: flex;
  flex-direction: column;
  gap: 18px;
  align-items: center;
  padding: 12px 0;
}
.symbol {
  width: 96px;
  height: 96px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.02),
    rgba(0, 0, 0, 0.06)
  );
  color: var(--white);
  font-family: "Montserrat", sans-serif;
  border: 1px solid rgba(255, 255, 255, 0.04);
  text-shadow: 0 3px 12px rgba(0, 0, 0, 0.6);
}

